// Sheet rows -> { projects:[{project_id,name,active}] }. Tolerant of header naming.
const pick = (row, keys) => { for (const k of Object.keys(row)) if (keys.includes(k.trim().toLowerCase())) return row[k]; };
const ID = ['project id', 'project_id', 'projectid', 'id'];
const NAME = ['project name', 'project_name', 'project', 'name'];
const STATUS = ['status', 'active', 'state'];
const seen = new Set(), projects = [];
for (const { json: row } of $input.all()) {
  const name = String(pick(row || {}, NAME) ?? '').trim();
  if (!name) continue;
  const project_id = String(pick(row, ID) ?? '').trim() || name;
  const status = String(pick(row, STATUS) ?? 'active').trim().toLowerCase();
  const active = !['completed', 'cancelled', 'canceled', 'inactive', 'archived', 'closed', 'done', 'false', 'no', '0'].includes(status);
  const key = project_id.toLowerCase(); if (seen.has(key)) continue; seen.add(key);
  projects.push({ project_id, name, active });
}
return [{ json: { projects } }];

const norm = s => String(s ?? '').toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
const hash = str => { let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < str.length; i++) { const c = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ c, 2654435761); h2 = Math.imul(h2 ^ c, 1597334677); }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (h2 >>> 0).toString(16).padStart(8, '0') + (h1 >>> 0).toString(16).padStart(8, '0'); };
// Dice similarity on bigrams: tolerant of misheard names ("cue four campaign").
const dice = (a, b) => { a = norm(a).replace(/ /g, ''); b = norm(b).replace(/ /g, '');
  if (a === b) return 1; if (a.length < 2 || b.length < 2) return 0;
  const m = new Map(); for (let i = 0; i < a.length - 1; i++) { const g = a.slice(i, i + 2); m.set(g, (m.get(g) || 0) + 1); }
  let hit = 0; for (let i = 0; i < b.length - 1; i++) { const g = b.slice(i, i + 2); const n = m.get(g) || 0; if (n) { m.set(g, n - 1); hit++; } }
  return (2 * hit) / (a.length + b.length - 2); };
const rank = (query, projects) => projects
  .map(p => ({ p, score: dice(query, p.name) + norm(query).split(' ').filter(t => t && norm(p.name).includes(t)).length * 0.25 }))
  .sort((x, y) => y.score - x.score);

const body = $('Webhook get_projects').first().json.body || {};
const search = String((body.args || body).search || '').trim();
const active = ($input.first().json.projects || []).filter(p => p.active);
let list = active, matched = false;
if (search) { const r = rank(search, active); matched = r.length > 0 && r[0].score >= 0.5; list = r.map(x => x.p); }
const projects = list.slice(0, 50).map(p => ({ project_id: p.project_id, name: p.name }));
return [{ json: { response: projects.length
  ? { success: true, total: active.length, search_matched: matched,
      suggestions: projects.slice(0, 3).map(p => p.name),
      instruction: 'Speak at most three project names per turn, starting with suggestions.', projects }
  : { success: false, error_code: 'NO_PROJECTS', message: 'No active projects are available.' } } }];

