  return (2 * hit) / (a.length + b.length - 2); };
const rank = (query, projects) => projects
  .map(p => ({ p, score: dice(query, p.name) + norm(query).split(' ').filter(t => t && norm(p.name).includes(t)).length * 0.25 }))
  .sort((x, y) => y.score - x.score);

// Validates the Retell payload and resolves the project. Never trusts the LLM blindly.
const fail = (error_code, message, extra = {}) => [{ json: { valid: false, response: { success: false, error_code, message, ...extra } } }];
const body = $('Webhook create_task').first().json.body || {};
const call = body.call || {};
const a = body.args || body;            // supports "Payload: args only" too

const task_description = String(a.task_description || '').replace(/\s+/g, ' ').trim();
let steps = Array.isArray(a.high_level_steps) ? a.high_level_steps : (a.high_level_steps ? String(a.high_level_steps).split(/\n|;/) : []);
steps = steps.map(s => String(s).trim()).filter(Boolean); if (!steps.length) steps = ['Not yet defined'];
const minutes = Number(a.estimated_minutes);
const reqName = String(a.project_name || a.project_id || '').replace(/\s+/g, ' ').trim();
const wantsCreate = a.create_new_project === true || String(a.create_new_project).toLowerCase() === 'true';

const errors = [];
if (!reqName) errors.push('project_name is required');
if (task_description.length < 3) errors.push('task_description too short');
if (task_description.length > 500) errors.push('task_description too long');
if (!Number.isInteger(minutes) || minutes < 1 || minutes > 100000) errors.push('estimated_minutes must be a positive whole number');
if (errors.length) return fail('VALIDATION_ERROR', errors.join('; '));

const all = $('Normalize projects (create_task)').first().json.projects || [];
const active = all.filter(p => p.active);
let project = active.find(p => String(p.project_id) === reqName) || active.find(p => norm(p.name) === norm(reqName));
let needs_new_project = false;

if (!project) {
  const archived = all.find(p => !p.active && norm(p.name) === norm(reqName));
  if (archived) return fail('PROJECT_ARCHIVED', `"${archived.name}" is completed or closed. Ask the user for another project, or whether they want a new one.`);
  const ranked = rank(reqName, active);
  const suggestions = ranked.slice(0, 3).map(x => x.p.name);
  // Near identical name (likely transcription variance): do not create a duplicate, ask the user.
  if (ranked[0] && ranked[0].score >= 0.85 && wantsCreate)
    return fail('PROJECT_SIMILAR_EXISTS', `A very similar project "${ranked[0].p.name}" already exists. Ask the user if they meant that one before creating a new project.`, { suggestions });
  if (!wantsCreate)
    return fail('PROJECT_NOT_FOUND', `No project called "${reqName}". Offer up to three of these: ${suggestions.join(', ') || 'none'}. If the user wants a new project, confirm the exact name and call create_task again with create_new_project true.`, { requested_project: reqName, suggestions });
  if (reqName.length < 2 || reqName.length > 80) return fail('VALIDATION_ERROR', 'New project name must be 2 to 80 characters.');
  project = { project_id: reqName, name: reqName, active: true };   // sheet has no ID column: name is the key
  needs_new_project = true;
}

const created_at = new Date().toISOString();
const idempotency_key = hash([call.call_id || 'no-call', String(project.project_id), norm(task_description)].join('|'));
return [{ json: { valid: true, needs_new_project, idempotency_key, created_at,
  project, task_description, steps, minutes, call } }];

// Matches the projects tab: Name | Project Owner | Status | Start Date | Due Date
const r = $('Resolve project and validate').first().json;
const d = new Date(r.created_at);
const M = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const start = `${String(d.getUTCDate()).padStart(2, '0')}-${M[d.getUTCMonth()]}-${d.getUTCFullYear()}`;
return [{ json: { 'Name': r.project.name, 'Project Owner': '', 'Status': 'Active', 'Start Date': start, 'Due Date': '' } }];

// Retell retries failed requests and callers can confirm twice: block duplicates by idempotency key.
const r = $('Resolve project and validate').first().json;
const existing = $input.all().map(i => i.json || {}).find(row =>
  String(row['Idempotency Key'] ?? row.idempotency_key ?? '') === r.idempotency_key);
return [{ json: { duplicate: !!existing, existing_task_id: existing ? (existing['Task ID'] || existing.task_id || '') : '' } }];

// Same schema as the Fireflies pipeline (Tasks tab) plus Project and Idempotency Key.
const r = $('Resolve project and validate').first().json;
const c = r.call || {};
const task_id = 'voice-' + r.idempotency_key.slice(0, 10);
const steps = r.steps.map((s, i) => `${i + 1}. ${s}`).join('\n');
const effort = r.minutes >= 60 ? `${+(r.minutes / 60).toFixed(2)} h (${r.minutes} min)` : `${r.minutes} min`;
return [{ json: {
  'Task ID': task_id,
  'Meeting ID': c.call_id || '',
  'Meeting Title': 'Nudge Voice Call',
  'Meeting Date': c.start_timestamp ? new Date(c.start_timestamp).toISOString() : r.created_at,
  'Transcript ID': c.call_id || '',
  'Source': 'Nudge Voice',
  'Task': r.task_description,
  'Description': `${r.task_description}\nSteps:\n${steps}`,
  'Owner': '',
  'Due Date': '',
  'Priority': 'Unknown',
  'Estimated Effort': effort,
  'Evidence': 'Read back to and confirmed by the caller on a Nudge voice call',
  'AI Confidence': 'High',
  'Review Status': 'Pending Review',
  'Task Status': 'Not Started',
  'Review Notes': r.needs_new_project ? `New project "${r.project.name}" created by voice` : '',
  'Created At': r.created_at,
  'Project': r.project.name,
  'Idempotency Key': r.idempotency_key
} }];

const r = $('Resolve project and validate').first().json;
const row = $('Build task row').first().json;
return [{ json: { response: { success: true, duplicate: false, task_id: row['Task ID'],
  project_name: r.project.name, project_created: r.needs_new_project,
  message: r.needs_new_project
    ? `New project "${r.project.name}" created and task saved. Confirm both briefly, then ask if there is another task.`
    : 'Task saved. Confirm briefly and ask if there is another task.' } } }];
